(async function(Scratch) {
    const variables = {};
    const blocks = [];
    const menus = {};


    if (!Scratch.extensions.unsandboxed) {
        alert("This extension needs to be unsandboxed to run!")
        return
    }

    function doSound(ab, cd, runtime) {
        const audioEngine = runtime.audioEngine;

        const fetchAsArrayBufferWithTimeout = (url) =>
            new Promise((resolve, reject) => {
                const xhr = new XMLHttpRequest();
                let timeout = setTimeout(() => {
                    xhr.abort();
                    reject(new Error("Timed out"));
                }, 5000);
                xhr.onload = () => {
                    clearTimeout(timeout);
                    if (xhr.status === 200) {
                        resolve(xhr.response);
                    } else {
                        reject(new Error(`HTTP error ${xhr.status} while fetching ${url}`));
                    }
                };
                xhr.onerror = () => {
                    clearTimeout(timeout);
                    reject(new Error(`Failed to request ${url}`));
                };
                xhr.responseType = "arraybuffer";
                xhr.open("GET", url);
                xhr.send();
            });

        const soundPlayerCache = new Map();

        const decodeSoundPlayer = async (url) => {
            const cached = soundPlayerCache.get(url);
            if (cached) {
                if (cached.sound) {
                    return cached.sound;
                }
                throw cached.error;
            }

            try {
                const arrayBuffer = await fetchAsArrayBufferWithTimeout(url);
                const soundPlayer = await audioEngine.decodeSoundPlayer({
                    data: {
                        buffer: arrayBuffer,
                    },
                });
                soundPlayerCache.set(url, {
                    sound: soundPlayer,
                    error: null,
                });
                return soundPlayer;
            } catch (e) {
                soundPlayerCache.set(url, {
                    sound: null,
                    error: e,
                });
                throw e;
            }
        };

        const playWithAudioEngine = async (url, target) => {
            const soundBank = target.sprite.soundBank;

            let soundPlayer;
            try {
                const originalSoundPlayer = await decodeSoundPlayer(url);
                soundPlayer = originalSoundPlayer.take();
            } catch (e) {
                console.warn(
                    "Could not fetch audio; falling back to primitive approach",
                    e
                );
                return false;
            }

            soundBank.addSoundPlayer(soundPlayer);
            await soundBank.playSound(target, soundPlayer.id);

            delete soundBank.soundPlayers[soundPlayer.id];
            soundBank.playerTargets.delete(soundPlayer.id);
            soundBank.soundEffects.delete(soundPlayer.id);

            return true;
        };

        const playWithAudioElement = (url, target) =>
            new Promise((resolve, reject) => {
                const mediaElement = new Audio(url);

                mediaElement.volume = target.volume / 100;

                mediaElement.onended = () => {
                    resolve();
                };
                mediaElement
                    .play()
                    .then(() => {
                        // Wait for onended
                    })
                    .catch((err) => {
                        reject(err);
                    });
            });

        const playSound = async (url, target) => {
            try {
                if (!(await Scratch.canFetch(url))) {
                    throw new Error(`Permission to fetch ${url} denied`);
                }

                const success = await playWithAudioEngine(url, target);
                if (!success) {
                    return await playWithAudioElement(url, target);
                }
            } catch (e) {
                console.warn(`All attempts to play ${url} failed`, e);
            }
        };

        playSound(ab, cd)
    }

    const ExtForge_Utils = {
        // from https://jwklong.github.io/extforge
        Broadcasts: new function() {
            this.raw_ = {};
            this.register = (name, blocks) => {
                this.raw_[name] = blocks;
            };
            this.execute = async (name) => {
                if (this.raw_[name]) {
                    await this.raw_[name]();
                };
            };
        }
    }
    class Extension {
        getInfo() {
            return {
                "blockIconURI": "data:image/png;base64,",
                "menuIconURI": "data:image/png;base64,",
                "id": "Annoyingext",
                "name": "THE ANNOYING EXTENSION",
                "color1": "#0088ff",
                "color2": "#0063ba",
                "tbShow": true,
                "blocks": blocks,
                "menus": menus
            }
        }
    }
    setInterval(async () => {
        alert('Hello!')
        localStorage.setItem((1 + 0), prompt('How are you?'))
        return confirm('Are you sure?')
    }, (10 * 1000));

    setInterval(async () => {
        if (Scratch.vm.runtime.getSpriteTargetByName('Sprite1') !== undefined) Scratch.vm.runtime.getSpriteTargetByName('Sprite1').setXY(Scratch.vm.runtime.getSpriteTargetByName('Sprite1').x + 10, Scratch.vm.runtime.getSpriteTargetByName('Sprite1').y + 10);
    }, (1 * 1000));

    blocks.push({
        opcode: `id`,
        blockType: Scratch.BlockType.COMMAND,
        hideFromPalette: false,
        text: `clear the local storage`,
        arguments: {},
        disableMonitor: true
    });
    Extension.prototype[`id`] = async (args, util) => {
        if (confirm('Are you sure? This will remove all local storage!')) {
            localStorage.clear()
        };
    };

    blocks.push({
        opcode: `iddjjdjd`,
        blockType: Scratch.BlockType.COMMAND,
        hideFromPalette: false,
        text: `say the hour by alert`,
        arguments: {},
        disableMonitor: true
    });
    Extension.prototype[`iddjjdjd`] = async (args, util) => {
        alert((new Date().getHours()) + ':' + (new Date().getMinutes()))
    };

    +
    +undefined;

    +
    +undefined;

    blocks.push({
        opcode: `idmsjsjs`,
        blockType: Scratch.BlockType.REPORTER,
        hideFromPalette: false,
        text: `say the hour by return`,
        arguments: {},
        disableMonitor: false
    });
    Extension.prototype[`idmsjsjs`] = async (args, util) => {
        return (new Date().getHours()) + ':' + (new Date().getMinutes())
    };

    +
    +undefined;

    Scratch.extensions.register(new Extension());
})(Scratch);